/* Read-only connection health. No archived slot is interpreted as current availability. */
(() => {
 const host=document.querySelector('#availability-state');if(!host)return;
 const select=document.querySelector('#facility'),date=document.querySelector('#availability-date'),retry=document.querySelector('#availability-retry');let request;
 const F=window.SportsForms;
 const messages={loading:['Checking connection.','Reading the local service configuration. This does not check or reserve a slot.'],unavailable:['Availability is not connected.','No verified live facility feed is connected to this redesign. Use the current booking website or contact the sports council.'],empty:['No published slots.','No slot records were supplied for this selection. This does not mean the facility is free or closed.'],error:['The status could not be read.','The connection information could not be loaded. Try again, or check the current booking website. No availability can be confirmed.']};
 function show(state){const [title,copy]=messages[state];host.dataset.state=state;host.setAttribute('aria-busy',state==='loading'?'true':'false');host.querySelector('small').textContent=state==='loading'?'Connection check':state==='empty'?'No slot data':state==='error'?'Connection error':'Service unavailable';host.querySelector('h2').textContent=title;host.querySelector('p').textContent=copy;retry.disabled=state==='loading';}
 async function load(){request?.abort();request=new AbortController();const thisRequest=request;show('loading');const timer=setTimeout(()=>request===thisRequest&&thisRequest.abort('timeout'),8000);try{const response=await fetch('assets/services/connection.json',{cache:'no-store',signal:thisRequest.signal});if(!response.ok)throw Error('configuration response');const data=await response.json();if(data.schema!==1||!['unavailable','empty'].includes(data.availability?.status))throw Error('unverified response');if(thisRequest!==request)return;show(data.availability.status);}catch(err){if(thisRequest===request)show('error');}finally{clearTimeout(timer);}}
 function sync(push=true){const u=new URL(location.href);u.searchParams.set('facility',select.value);u.searchParams.set('date',date.value);if(push)history.pushState(null,'',u);document.querySelector('#selected-facility').textContent=select.value;load();}
 function restore(){const u=new URL(location.href);select.value=u.searchParams.get('facility')||'Badminton';if(select.selectedIndex<0)select.value='Badminton';const supplied=u.searchParams.get('date');date.value=/^\d{4}-\d{2}-\d{2}$/.test(supplied||'')?supplied:F.istDate();if(!date.value)date.value=F.istDate();sync(false);}
 select.addEventListener('change',()=>sync());date.addEventListener('change',()=>{if(!date.value)date.value=F.istDate();sync();});retry.addEventListener('click',load);window.addEventListener('popstate',restore);window.addEventListener('pagehide',()=>request?.abort());document.querySelectorAll('[data-enhanced]').forEach(el=>el.hidden=false);restore();
})();
